    mstore(sessionKeyHash, 0x20)
    mstore(add(sessionKeyHash, 0x20), sessionKeyHash_bytes32)
}

{
    let tmp := mload(add(from, i))
    mstore(add(to, j), tmp)
}

{
    let size := mload(0x40)
    mstore(size, hash)
    mstore(add(size, 32), v)
    mstore(add(size, 64), r)
    mstore(add(size, 96), s)
    ret := call(3000, 1, 0, size, 128, size, 32)
    addr := mload(size)
}

{
    r := mload(add(sig, 32))
